function lcs(a, b)
    dp = table with length(a) + 1 rows and length(b) + 1 columns, all 0

    for i = 1 to length(a)
        for j = 1 to length(b)
            if a[i - 1] == b[j - 1]
                dp[i][j] = dp[i - 1][j - 1] + 1
            else
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[length(a)][length(b)]
